SELECT CASE WHEN o.discount >= 0.38 THEN 'high' WHEN o.discount >= 0.17 THEN 'mid' ELSE 'low' END discount_bucket, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(p.status))) status_values, MAX(p.amount) - MIN(p.amount) amount_range FROM payments p INNER JOIN orders o ON p.order_id = o.id WHERE TO_DATE(p.paid_at) < '2023-12-01' GROUP BY CASE WHEN o.discount >= 0.38 THEN 'high' WHEN o.discount >= 0.17 THEN 'mid' ELSE 'low' END;
